  : (raw || {});
const ajustes = out.criterios_ajustados || {};
const criterios = { ...base.criterios };
const aplicadas = {};
const rechazadas = {};

// Valores permitidos por clave -- si la IA escribe algo fuera de esta lista para una clave
// controlada, se descarta el ajuste en vez de aplicarlo (evita corromper el criterio en
// silencio, p.ej. valores de organizacion_juridica escritos por error en tamano_empresa).
const VALORES_VALIDOS = {
  organizacion_juridica: ['Personas Jurídicas', 'Personas Naturales', 'Establecimientos', 'Entidades sin ánimo de lucro'],
  tamano_empresa: ['Microempresas', 'Pequeñas empresas', 'Medianas empresas', 'Grandes empresas'],
  actividad_economica: ['Agropecuario', 'Minero', 'Industria', 'Electricidad, gas, vapor y aire acondicionado', 'Agua', 'Construcción', 'Comercio al por mayor y al por menor', 'Transporte', 'Alojamiento y restaurantes', 'Información y comunicaciones', 'Financiero', 'Inmobiliarias', 'Profesionales, científicas y técnicas', 'Servicios administrativos y de apoyo', 'Educación', 'Salud', 'Artísticas, de entretenimiento y recreación', 'Otras actividades de servicios', 'Todas las actividades económicas']
};

function esValorValido(clave, valor) {
  const permitidos = VALORES_VALIDOS[clave];
  if (!permitidos) return true;
  const partes = String(valor).split(';').map(s => s.trim()).filter(Boolean);
  if (!partes.length) return false;
  return partes.every(p => permitidos.includes(p));
}

for (const [k, v] of Object.entries(ajustes)) {
  if (!Object.prototype.hasOwnProperty.call(criterios, k)) continue;
  if (esValorValido(k, v)) { criterios[k] = v; aplicadas[k] = v; }
  else { rechazadas[k] = v; }
}

const huboRechazos = Object.keys(rechazadas).length > 0;
const avisoRechazo = huboRechazos
  ? ' [AVISO: se descartaron ajustes invalidos para: ' + Object.keys(rechazadas).join(', ') + ' -- valor(es) no reconocido(s): ' + JSON.stringify(rechazadas) + ']'
  : '';

return { json: { id_solicitud: base.id_solicitud, servicio: base.servicio, criterios, criterios_ajustados_aplicados: aplicadas, criterios_ajustados_rechazados: rechazadas, resumen_cambios: (out.resumen_cambios || '') + avisoRechazo, comentario: base.Comentario || '' } };

